import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();

  // Load and clone the gear mesh
  const gearOriginal = ctx.glbLoader.get(config.meshUrl);
  const gearClone = gearOriginal.clone(true);

  // Apply scene placement
  const { position, rotation, scale } = config.scenePlacement;
  gearClone.position.set(position.x, position.y, position.z);
  gearClone.rotation.set(rotation.x, rotation.y, rotation.z);
  gearClone.scale.set(scale.x, scale.y, scale.z);
  root.add(gearClone);

  // Prepare GSAP timelines for interactions
  const tlHover = gsap.timeline({ paused: true });
  tlHover.to(gearClone.position, {
    y: gearClone.position.y + 0.15,
    duration: 0.5,
    ease: 'power3.out',
    overwrite: 'auto'
  }, 0);

  const tlPress = gsap.timeline({ paused: true });
  tlPress.to(gearClone.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(1.7)',
    overwrite: 'auto'
  }, 0);
  tlPress.to(gearClone.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.3,
    ease: 'power4.out',
    overwrite: 'auto'
  }, 0.12);

  // Interaction handlers
  root.userData.handlers = {
    pointerover: () => {
      tlHover.play();
    },
    pointerout: () => {
      tlHover.reverse();
    },
    click: () => {
      tlPress.restart();
      // Emit navigation event
      if (config.onEvent) {
        config.onEvent('hub-home.select', { target: root });
      }
    }
  };

  // Apply cinematic primitives
  (config.cinematicPrimitives || []).forEach(primitive => {
    const applyFn = ctx.primitives[primitive.name];
    if (applyFn) {
      applyFn(root, primitive.params);
    }
  });

  // Cleanup
  root.userData.cleanup = () => {
    tlHover.kill();
    tlPress.kill();
    // Traverse to dispose materials/geometries if needed (shared via cache)
    root.traverse(child => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material?.dispose();
        }
      }
    });
  };

  return root;
}
